/**
 * Validates the pipeline against the reproducible synthetic profile in data/demo (generated by
 * data/generator/generate_synthetic_profile.py). Expected values come from expected.json, which the generator computes
 * independently from its own labels; labels.csv is used ONLY to score the categorizer, never as an input to it.
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { beforeEach, describe, expect, it } from "vitest";
import { appRouter } from "../routers";
import type { TrpcContext } from "../_core/context";
import { parseCsv } from "./ingestion/csv";
import { FileLedgerRepository, setLedgerRepositoryForTests } from "./ledger";
import { _previewStoreForTests } from "./service";

const DIR = path.resolve(__dirname, "../../data/demo");
const read = (n: string) => readFileSync(path.join(DIR, n), "utf8");
const expected = JSON.parse(read("expected.json"));
const LAYOUTS = ["fixture_debit_credit.csv", "fixture_signed_amount.csv", "fixture_bank_statement.csv"] as const;

const ctx = (key: string): TrpcContext => ({
  user: { id: 5, openId: "x", email: null, name: "D", loginMethod: "l", role: "user", createdAt: new Date(), updatedAt: new Date(), lastSignedIn: new Date() },
  req: { protocol: "http", headers: {} } as TrpcContext["req"],
  res: { clearCookie: () => undefined } as unknown as TrpcContext["res"],
  inariUserKey: key,
  inariIdentityKind: "anonymous_demo",
});
const as = (i: number) => appRouter.createCaller(ctx(`anon:00000000-0000-4000-8000-0000000fi${String(i).padStart(3, "0")}`.replace("fi", "00")));

beforeEach(() => {
  setLedgerRepositoryForTests(new FileLedgerRepository());
  _previewStoreForTests.clear();
});

describe("fixture integrity", () => {
  it("every committed file matches MANIFEST.sha256", () => {
    for (const line of read("MANIFEST.sha256").trim().split("\n")) {
      const [hash, name] = line.split(/\s+/);
      expect(createHash("sha256").update(readFileSync(path.join(DIR, name))).digest("hex"), name).toBe(hash);
    }
  });
  it("has roughly 500 rows, no category column in any importable layout, and is fictional", () => {
    expect(expected.rows).toBeGreaterThanOrEqual(450);
    for (const f of LAYOUTS) {
      const header = read(f).split("\n").find(l => /^Date,/.test(l))!.toLowerCase();
      expect(header).not.toMatch(/categor|recurring/);
    }
    expect(read("fixture_bank_statement.csv")).toMatch(/SYNTHETIC/);
  });
});

describe("each layout imports completely and yields the independently computed snapshot", () => {
  for (const [i, layout] of LAYOUTS.entries()) {
    it(layout, async () => {
      const c = as(i + 1);
      const p = await c.inari.importPreview({ kind: "csv", filename: layout, content: read(layout) });
      expect(p.counts).toMatchObject({ accepted: expected.rows, rejected: 0, duplicate: 0 });
      await c.inari.importCommit({ previewId: p.previewId });
      const s = await c.inari.getSnapshot();
      expect(s.coverage).toMatchObject({ completeMonths: 6, firstDate: expected.first_date, lastDate: expected.last_date, transactionCount: expected.rows });
      expect(s.monthlyIncome).toBe(expected.snapshot.monthlyIncome);
      expect(s.monthlyExpenses).toBe(expected.snapshot.monthlyExpenses);
      expect(s.monthlySurplus).toBeCloseTo(expected.snapshot.monthlySurplus, 2);
      expect(s.savingsRate).toBeCloseTo(expected.snapshot.savingsRate, 1);
      expect(s.balances).toEqual({ emergencyFund: null, investments: null, creditCardDebt: null });
    });
  }

  it("all three layouts produce identical ledgers (same ids and categories)", async () => {
    const ledgers: string[] = [];
    for (const [i, layout] of LAYOUTS.entries()) {
      const c = as(10 + i);
      const p = await c.inari.importPreview({ kind: "csv", filename: layout, content: read(layout) });
      await c.inari.importCommit({ previewId: p.previewId });
      const items = (await c.inari.listTransactions({ limit: 200 })).items;
      let cursor: string | null = null;
      const all: typeof items = [];
      do {
        const page = await c.inari.listTransactions({ limit: 200, cursor: cursor ?? undefined });
        all.push(...page.items);
        cursor = page.nextCursor;
      } while (cursor);
      ledgers.push(JSON.stringify(all.map(t => [t.postedOn, t.amountPaise, t.direction, t.category]).sort()));
    }
    expect(ledgers[1]).toBe(ledgers[0]);
    expect(ledgers[2]).toBe(ledgers[0]);
  });

  it("re-importing a different layout of the same period is NOT silently double counted", async () => {
    const c = as(20);
    const first = await c.inari.importPreview({ kind: "csv", filename: "a.csv", content: read(LAYOUTS[0]) });
    await c.inari.importCommit({ previewId: first.previewId });
    const second = await c.inari.importPreview({ kind: "csv", filename: "b.csv", content: read(LAYOUTS[1]) });
    // narrations are identical, so row identity matches even though the layout differs
    expect(second.counts.accepted).toBe(0);
    expect(second.counts.duplicate).toBe(expected.rows);
  });
});

describe("categorizer vs held-out labels (labels never fed to the classifier)", () => {
  it("reaches the documented accuracy floor and never labels a debit as salary", async () => {
    const c = as(30);
    const p = await c.inari.importPreview({ kind: "csv", filename: "x.csv", content: read(LAYOUTS[0]) });
    await c.inari.importCommit({ previewId: p.previewId });
    const rows: Awaited<ReturnType<typeof c.inari.listTransactions>>["items"] = [];
    let cursor: string | undefined;
    do {
      const page = await c.inari.listTransactions({ limit: 200, cursor });
      rows.push(...page.items);
      cursor = page.nextCursor ?? undefined;
    } while (cursor);

    const labels = parseCsv(read("labels.csv"), { maxRows: 10_000 }).records.slice(1).map(r => ({ date: r.cells[1], narration: r.cells[2], amount: r.cells[4], category: r.cells[5] }));
    const key = (d: string, n: string, a: string) => `${d}|${n}|${a}`;
    const pool = new Map<string, string[]>();
    for (const l of labels) pool.set(key(l.date, l.narration, l.amount), [...(pool.get(key(l.date, l.narration, l.amount)) ?? []), l.category]);

    let hit = 0;
    const misses = new Map<string, number>();
    for (const t of rows) {
      const want = pool.get(key(t.postedOn, t.narration, t.amount.toFixed(2)))?.shift();
      const wantCategory = want === "cc_repayment" ? "other" : want; // generator-specific label
      if (t.category === wantCategory) hit++;
      else misses.set(`${wantCategory}->${t.category}`, (misses.get(`${wantCategory}->${t.category}`) ?? 0) + 1);
    }
    const accuracy = hit / rows.length;
    // eslint-disable-next-line no-console
    console.log(`categorizer accuracy on fixture: ${(accuracy * 100).toFixed(1)}% (${hit}/${rows.length}); misses:`, Object.fromEntries(misses));
    expect(accuracy).toBeGreaterThanOrEqual(0.95);
    expect(rows.filter(t => t.direction === "debit" && t.category === "salary")).toHaveLength(0);
  });
});
